def level_from_legacy_selection_unit(apps, schema_editor):
    """Existing span-unit recipes keep their grain; the rest are conversations.

    The legacy recipe fields (formula, inputs, selection_unit) stay unchanged.
    """
    DerivedMetricVersion = apps.get_model("tracer", "DerivedMetricVersion")
    DerivedMetricVersion.objects.filter(selection_unit="span").update(level="span")


